{"operation":"run_python","code":"import urllib.request
import json
import re

def get_release_date(title):
    url = f"https://en.wikipedia.org/w/api.php?action=query&titles={title}&prop=revisions&rvprop=content&rvslots=main&format=json"
    try:
        req = urllib.request.urlopen(url)
        data = json.loads(req.read())
        pages = data['query']['pages']
        for page_id, page in pages.items():
            if page_id == '-1':
                return "Not found"
            content = page['revisions'][0]['*']
            # Look for release year in infobox or intro
            match = re.search(r'\| ?released ?\| ?(\d{4})', content, re.IGNORECASE)
            if match:
                return match.group(1)
            # fallback
            match2 = re.search(r'\(\d{4}\)', content[:500])
            if match2:
                return match2.group(0).strip('()')
    except Exception as e:
        return str(e)
    return "Not found"

sp = get_release_date("Saint Petersburg (board game)")
fio = get_release_date("Figure It Out (board game)")
print(f"Saint Petersburg: {sp}")
print(f"Figure It Out: {fio}")
"}

